  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "যে কন্টাক্টদের জন্মদিন আছে, মনে করানোর জন্য অ্যাপ তাদের নাম, জন্মদিন আর ছবি পড়ে। সেগুলো এই ফোনেই থাকে, কখনও আপলোড হয় না।",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "বড় বাজিগুলোর দাম জেম। রোজকার বাজি আর ফুলঝুরিতে লেখা সবসময় বিনামূল্যে।",
