  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "লিঙ্কের মধ্যেই পুরো কার্ড আছে, তাই কিছু আপলোড হয় না। যে খুলবে সে-ই শো দেখবে।",
