  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR ছবিগুলো চিত্রায়ণ; আপনার ফোনে দেখতে কেমন হবে তা ক্যামেরা আর ঘরের ওপর নির্ভর করে। আসল মেঝেতে AR বাজির জন্য Google Play Services for AR সমর্থিত ফোন লাগবে।",
