  "Cards you make are kept here, ready to play, change or send again.": "তোমার বানানো কার্ড এখানে রাখা থাকে, আবার চালাতে, বদলাতে বা পাঠাতে।",
  "Cards friends send you are kept here, so you can watch them again.": "বন্ধুদের পাঠানো কার্ড এখানে রাখা থাকে, যাতে আবার দেখতে পারো।",
