  "Missing you more than words can say. This sky is for you.": "কথায় বলা যায় না, এতটা মনে পড়ছে তোমায়। এই আকাশটা তোমার জন্য।",
  "🌻 Get well": "🌻 সেরে ওঠো",
  "Get well": "সেরে ওঠো",
  "Get Well Soon": "তাড়াতাড়ি সেরে ওঠো",
  "Sending you healing wishes and a sky full of light. Get well soon!": "সেরে ওঠার শুভকামনা আর আলোয় ভরা একটা আকাশ পাঠালাম। তাড়াতাড়ি সেরে ওঠো!",
  "🌈 Just because": "🌈 এমনিই",
  "Just because": "এমনিই",
