  "Premium cards hold up to 10 reasons they turn through after the show. Plus no ads and every cracker free.": "প্রিমিয়াম কার্ডে শো-এর পরে পাতা উল্টে দেখার মতো সর্বোচ্চ ১০টি কারণ রাখা যায়। সঙ্গে কোনও বিজ্ঞাপন নেই আর সব বাজি ফ্রি।",
  "1 reason": "১টি কারণ",
  "{0} reasons": "{0}টি কারণ",
  "You brighten my days in so many ways. Here are a few": "কত ভাবেই না তুমি আমার দিনগুলো আলো করে দাও। এই রইল কয়েকটা",
  "I love how kind you are, even when nobody is looking": "কেউ না দেখলেও তুমি কত দয়ালু, এটা আমার খুব ভালো লাগে",
  "Your smile can light up a whole room": "তোমার হাসি গোটা ঘর আলো করে দিতে পারে",
  "I love that every chat with you ends in laughter": "তোমার সঙ্গে প্রতিটা গল্প হাসিতে শেষ হয়, এটা আমার খুব ভালো লাগে",
  "I still smile when I think of the fun we’ve had": "আমাদের মজার দিনগুলোর কথা ভাবলে আজও হাসি পায়",
  "When things got hard, you were there without being asked": "কঠিন সময়ে না বলতেই তুমি পাশে ছিলে",
  "Thanks for always making time for me": "সবসময় আমার জন্য সময় বের করার জন্য ধন্যবাদ",
  "Thank you for believing in me": "আমায় বিশ্বাস করার জন্য ধন্যবাদ",
  "I’m so proud of how far you’ve come": "তুমি কতটা পথ পেরিয়ে এসেছ, তা নিয়ে আমি খুব গর্বিত",
  "And a thousand more reasons that won’t fit here": "আর আরও হাজারটা কারণ, যা এখানে ধরবে না",
  "Most of all, thank you for simply being you": "সবচেয়ে বড় কথা, শুধু তুমি তুমিই থাকার জন্য ধন্যবাদ",
  "There are so many reasons you’re special. Here are a few": "তুমি কেন বিশেষ, তার এত কারণ। এই রইল কয়েকটা",
  "I love the way your eyes light up when you laugh": "তুমি হাসলে তোমার চোখ যেভাবে ঝলমল করে, সেটা আমার খুব প্রিয়",
  "You make ordinary days feel like festivals": "তুমি সাধারণ দিনগুলোকেও উৎসব বানিয়ে দাও",
  "Your kindness makes the world softer": "তোমার দয়ায় পৃথিবীটা আরও কোমল হয়ে ওঠে",
  "I love our long talks that never feel long enough": "আমাদের লম্বা গল্পগুলো আমার খুব প্রিয়, যা কখনও যথেষ্ট লম্বা মনে হয় না",
  "Every walk with you turns into an adventure": "তোমার সঙ্গে প্রতিটা হাঁটাই একটা অভিযান হয়ে যায়",
  "I still remember the first time you made me laugh": "প্রথমবার তুমি আমায় যেদিন হাসিয়েছিলে, আজও মনে আছে",
  "When I doubted myself, you believed in me": "যখন নিজেকে নিয়ে সন্দেহ হয়েছিল, তুমি আমায় বিশ্বাস করেছিলে",
  "Thanks for always listening, even to my silly stories": "আমার বোকা বোকা গল্পগুলোও সবসময় মন দিয়ে শোনার জন্য ধন্যবাদ",
  "I can’t wait to see all the good things coming your way": "তোমার জীবনে যত ভালো কিছু আসছে, দেখার জন্য আর তর সইছে না",
  "You light up my sky, every single day": "রোজ, প্রতিটা দিন তুমি আমার আকাশ আলো করে দাও",
  "And this is only the beginning of the list": "আর এটা তো তালিকার শুরু মাত্র",
  "You gave me everything, so here are a few things I love about you": "তুমি আমায় সবকিছু দিয়েছ, তাই তোমার কয়েকটা জিনিস যা আমার খুব প্রিয়",
  "You taught me to be brave": "তুমি আমায় সাহসী হতে শিখিয়েছ",
  "I love how you make everyone feel at home": "তুমি যেভাবে সবাইকে আপন করে নাও, সেটা আমার খুব ভালো লাগে",
  "Your hugs still fix almost everything": "তোমার একটা আদরে আজও প্রায় সব ঠিক হয়ে যায়",
  "I love our cups of chai and long talks": "আমাদের চায়ের কাপ আর লম্বা গল্পগুলো আমার খুব প্রিয়",
  "Cooking with you is my favourite kind of afternoon": "তোমার সঙ্গে রান্না করাই আমার সবচেয়ে প্রিয় দুপুর",
  "I still remember you waiting up for me every night": "আজও মনে পড়ে, রোজ রাতে তুমি আমার জন্য জেগে বসে থাকতে",
  "You never missed a single school function": "স্কুলের একটা অনুষ্ঠানও তুমি বাদ দাওনি",
  "When I felt like giving up, you held my hand": "যখন হাল ছেড়ে দিতে ইচ্ছে করেছিল, তুমি আমার হাত ধরেছিলে",
  "I never had to wonder if you loved me": "তুমি আমায় ভালোবাসো কিনা, এ নিয়ে কখনও ভাবতে হয়নি",
  "Thanks for every sacrifice you never talked about": "যে সব ত্যাগের কথা তুমি কখনও বলোনি, তার জন্য ধন্যবাদ",
  "Thank you for every prayer you said for me": "আমার জন্য করা প্রতিটা প্রার্থনার জন্য ধন্যবাদ",
  "Everything good in me started with you": "আমার মধ্যে যা কিছু ভালো, সব শুরু তোমার থেকে",
  "I’m proud to be your child, today and always": "আজ আর চিরকাল, তোমার সন্তান হতে পেরে আমি গর্বিত",
  "For all your stories and blessings, a few reasons I love you": "তোমার সব গল্প আর আশীর্বাদের জন্য, তোমায় ভালোবাসার কয়েকটা কারণ",
  "Your patience is endless, and so is your love": "তোমার ধৈর্যের শেষ নেই, তোমার ভালোবাসারও না",
  "You always know exactly what to say": "কখন কী বলতে হয়, তুমি সবসময় ঠিক জানো",
