  "Your kitchen always smells like love": "তোমার রান্নাঘরে সবসময় ভালোবাসার গন্ধ",
  "I remember the sweets you slipped into my pocket": "তুমি চুপি চুপি আমার পকেটে যে মিষ্টি গুঁজে দিতে, মনে আছে",
  "Afternoons at your house were the best part of childhood": "তোমার বাড়িতে কাটানো দুপুরগুলোই ছিল ছোটবেলার সেরা সময়",
  "When life felt confusing, your words made it simple": "জীবনটা যখন জটিল লাগত, তোমার কথায় সহজ হয়ে যেত",
  "Thank you for every blessing on my head": "আমার মাথায় রাখা প্রতিটা আশীর্বাদের জন্য ধন্যবাদ",
  "Thanks for teaching me the old songs and prayers": "পুরনো গান আর প্রার্থনাগুলো শেখানোর জন্য ধন্যবাদ",
  "Your wisdom guides our whole family": "তোমার জ্ঞানই আমাদের গোটা পরিবারকে পথ দেখায়",
