  "You always take my side, even when I’m wrong": "আমার ভুল হলেও তুমি সবসময় আমার পক্ষ নাও",
  "I love our late-night talks and secret jokes": "আমাদের রাত জাগা গল্প আর গোপন রসিকতাগুলো আমার খুব প্রিয়",
  "Fighting over the remote is still my favourite sport": "রিমোট নিয়ে মারামারিই আজও আমার প্রিয় খেলা",
  "I still laugh about the mischief we got away with as kids": "ছোটবেলায় যে সব দুষ্টুমি করে পার পেয়ে গেছি, ভাবলে আজও হাসি পায়",
  "Our childhood games are my happiest memories": "ছোটবেলার খেলাগুলোই আমার সবচেয়ে সুখের স্মৃতি",
  "When I felt alone, you showed up without a word": "যখন একা লাগত, তুমি কিছু না বলেই পাশে চলে আসতে",
  "Thanks for always keeping my secrets": "সবসময় আমার গোপন কথা লুকিয়ে রাখার জন্য ধন্যবাদ",
  "Thank you for sharing your snacks, mostly": "তোমার খাবারের ভাগ দেওয়ার জন্য ধন্যবাদ, বেশিরভাগ সময়ই",
  "I’m so proud of the person you’ve become": "তুমি যে মানুষ হয়ে উঠেছ, তা নিয়ে আমি খুব গর্বিত",
  "Lucky me, I got you for life": "কী ভাগ্য আমার, সারা জীবনের জন্য তোমায় পেয়েছি",
  "From the day you arrived, you gave me endless reasons to smile": "যেদিন তুমি এলে, সেদিন থেকে হাসার অফুরন্ত কারণ দিয়েছ",
  "I love your curious mind and your big heart": "তোমার কৌতূহলী মন আর বড় হৃদয় আমার খুব প্রিয়",
  "Your laugh is the best sound in our home": "তোমার হাসিই আমাদের ঘরের সবচেয়ে সুন্দর শব্দ",
  "You are braver than you know": "তুমি যতটা ভাবো, তার চেয়েও সাহসী",
