  "Bedtime stories with you are my favourite part of the day": "তোমার সঙ্গে ঘুমের আগের গল্পই আমার দিনের সবচেয়ে প্রিয় সময়",
  "I still remember holding your tiny hand for the first time": "প্রথমবার তোমার ছোট্ট হাতটা ধরার কথা আজও মনে আছে",
  "When I was tired, one hug from you made it all better": "ক্লান্ত লাগলে তোমার একটা আদরেই সব ঠিক হয়ে যেত",
  "Thank you for making me a parent": "আমায় বাবা-মা হওয়ার আনন্দ দেওয়ার জন্য ধন্যবাদ",
  "Thanks for teaching me to see the world with new eyes": "নতুন চোখে পৃথিবীটা দেখতে শেখানোর জন্য ধন্যবাদ",
  "Watching you grow is the greatest gift of my life": "তোমাকে বড় হতে দেখাই আমার জীবনের সবচেয়ে বড় উপহার",
  "Wherever you go, my love goes with you": "তুমি যেখানেই যাও, আমার ভালোবাসা তোমার সঙ্গে যায়",
  "Family like you makes every gathering brighter. Here’s why": "তোমার মতো আত্মীয় থাকলে প্রতিটা জমায়েত আরও উজ্জ্বল। এই রইল কেন",
  "You always make me feel welcome": "তুমি সবসময় আমায় আপন করে নাও",
  "Your laugh is the loudest at every family function": "পরিবারের প্রতিটা অনুষ্ঠানে তোমার হাসিই সবচেয়ে জোরে",
  "I love our chats over festival sweets": "উৎসবের মিষ্টি খেতে খেতে আমাদের গল্পগুলো আমার খুব প্রিয়",
  "Family weddings are more fun with you around": "তুমি থাকলে পরিবারের বিয়েবাড়িগুলো আরও জমে ওঠে",
  "I still remember the summer holidays at your place": "তোমার বাড়িতে কাটানো গরমের ছুটির কথা আজও মনে আছে",
