  "Chaos: points for the mischief your crackers cause (near people, stalls, roofs, the donkey). Found: today’s hidden stashes on this street.": "হইচই: আপনার বাজির দুষ্টুমির পয়েন্ট (মানুষ, দোকান, ছাদ, গাধার কাছে)। পাওয়া গেছে: এই গলিতে আজকের লুকোনো জায়গা।",
  "🏁 Home in {0} · waiting for the others": "🏁 {0}-এ পৌঁছেছেন · বাকিদের অপেক্ষা",
  "Carry 10 kinds of cracker, not 6. Yours for good": "৬ নয়, ১০ রকম বাজি নিয়ে চলুন। চিরকাল আপনার",
