  "🗝 Key complete! Steal the {0} from Seth-ji's vault": "🗝 চাবি সম্পূর্ণ! শেঠজির সিন্দুক থেকে {0} চুরি করুন",
  "🚨 You have the {0}! RUN to the gate 🏁": "🚨 {0} আপনার কাছে! গেটের দিকে দৌড়ান 🏁",
  "Seth-ji grabbed it! It fell at your feet. Snatch it back": "শেঠজি কেড়ে নিয়েছেন! এটি আপনার পায়ের কাছে পড়েছে। আবার ছিনিয়ে নিন",
  "🏆 The {0} is yours! It's in your trophy room": "🏆 {0} আপনার! এটি আপনার ট্রফি ঘরে আছে",
