  "🏆 Trophies": "🏆 ট্রফি",
  "This week's treasure: {0}. Race any street: find the 9 key pieces, open the vault, get it to the gate.": "এই সপ্তাহের ধন: {0}। যেকোনো গলিতে রেস করুন: 9টি চাবির টুকরো খুঁজুন, সিন্দুক খুলুন, গেট পর্যন্ত নিয়ে যান।",
  "🎭 Master Thief frame unlocked": "🎭 মাস্টার চোর ফ্রেম খুলেছে",
  "🎭 Master Thief frame: {0}/{1} heists": "🎭 মাস্টার চোর ফ্রেম: {0}/{1} চুরি",
